var rect = (width, height) => {
  const cells = [];
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) cells.push([x, y]);
  }
  return cells;
};
var shape = (...rows) => {
  const cells = [];
  rows.forEach((row, y) => {
    [...row].forEach((cell, x) => {
      if (cell !== ".") cells.push([x, y]);
    });
  });
  return cells;
};

