function applyNativeBlockRepair(level) {
  const rows = replacements[level.id];
  if (!rows) return level;
  const blocks = level.blocks.flatMap((block3) => {
    const row = rows.find((r) => r.sourceIds.includes(block3.id));
    if (!row) return [block3];
    return row.sourceIds[0] === block3.id ? row.blocks : [];
  });
  return { ...level, blocks };
}

